_ph = None; _pp = None
def _pecota():
    global _ph, _pp
    if _ph is None:
        raw = json.loads(_PECOTA_HIT_JSON)
        cleaned = [{k.strip(): (v.strip() if isinstance(v, str) else v) for k, v in row.items()} for row in raw]
        _ph = pd.DataFrame(cleaned)
        _ph["team_id"] = _ph["team"].map(PECOTA_TEAM_MAP)
        _ph = _ph.dropna(subset=["team_id"]); _ph["team_id"] = _ph["team_id"].astype(int)
    if _pp is None:
        raw = json.loads(_PECOTA_PIT_JSON)
        cleaned = [{k.strip(): (v.strip() if isinstance(v, str) else v) for k, v in row.items()} for row in raw]
        _pp = pd.DataFrame(cleaned)
        _pp["team_id"] = _pp["team"].map(PECOTA_TEAM_MAP)
        _pp = _pp.dropna(subset=["team_id"]); _pp["team_id"] = _pp["team_id"].astype(int)
    return _ph, _pp

def _sc_weights(sample, threshold):
    w = min(sample / threshold, 1.0)
    return w, 1.0 - w

def _fetch_statcast_hist(year, stat_type):
    try:
        import io
        url = f"https://baseballsavant.mlb.com/leaderboard/expected_statistics?type={stat_type}&year={year}&position=&team=&min=q&csv=true"
        r = requests.get(url, timeout=20, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code != 200 or len(r.content) < 500: return {}
        df = pd.read_csv(io.StringIO(r.content.decode("utf-8")))
        stat_col = "xwoba" if stat_type=="batter" else "xera"
        sample_col = "pa" if stat_type=="batter" else "p_formatted_ip"
        if stat_col not in df.columns or "team_id" not in df.columns: return {}
        if sample_col not in df.columns: sample_col = "ip" if "ip" in df.columns else None
        if sample_col is None: return {}
        df[stat_col] = pd.to_numeric(df[stat_col], errors="coerce")
        df[sample_col] = pd.to_numeric(df[sample_col], errors="coerce").fillna(0)
        df = df.dropna(subset=[stat_col])
        out = {}
        for tid, g in df.groupby("team_id"):
            if g[sample_col].sum() > 0:
                lo, hi = (0.100, 0.600) if stat_type=="batter" else (1.5, 8.0)
                out[int(tid)] = float(np.average(g[stat_col].clip(lo, hi), weights=g[sample_col].clip(1)))
        return out
    except Exception: return {}

def _fetch_statcast_current(year):
    import io
    bat_out = {}; pit_out = {}
    for stype, out, sc, samp in [("batter",bat_out,"xwoba","pa"),("pitcher",pit_out,"xera","p_formatted_ip")]:
        try:
            url = f"https://baseballsavant.mlb.com/leaderboard/expected_statistics?type={stype}&year={year}&position=&team=&min=1&csv=true"
            r = requests.get(url, timeout=20, headers={"User-Agent": "Mozilla/5.0"})
            if r.status_code != 200 or len(r.content) < 500: continue
            df = pd.read_csv(io.StringIO(r.content.decode("utf-8")))
            if sc not in df.columns or "team_id" not in df.columns: continue
            if samp not in df.columns: samp = "ip" if "ip" in df.columns else None
            if samp is None: continue
            df[sc] = pd.to_numeric(df[sc], errors="coerce")
            df[samp] = pd.to_numeric(df[samp], errors="coerce").fillna(0)
            df = df.dropna(subset=[sc])
            lo, hi = (0.100, 0.600) if stype=="batter" else (1.5, 8.0)
            for tid, g in df.groupby("team_id"):
                total = float(g[samp].sum())
                if total > 0: out[int(tid)] = {"stat": float(np.average(g[sc].clip(lo,hi), weights=g[samp].clip(1))), "sample": total}
        except Exception: continue
    return bat_out, pit_out

def _fetch_mlb_ops_era(year):
    bat = {}; pit = {}
    for group, out, key in [("hitting",bat,"ops"),("pitching",pit,"era")]:
        try:
            r = requests.get(f"{MLB_API_BASE}/teams/stats", params={"stats":"season","group":group,"season":year,"sportId":1}, timeout=10)
            if r.status_code != 200: continue
            for sg in r.json().get("stats",[]):
                for sp in sg.get("splits",[]):
                    tid = sp.get("team",{}).get("id")
                    val = sp.get("stat",{}).get(key)
                    if tid and val:
                        try: out[int(tid)] = float(val)
                        except: pass
        except: pass
    return bat, pit

def _load_statcast_all():
    """Fetch all Statcast signals in parallel. Returns dict of results."""
    with cf.ThreadPoolExecutor(max_workers=5) as ex:
        f25b = ex.submit(_fetch_statcast_hist, 2025, "batter")
        f25p = ex.submit(_fetch_statcast_hist, 2025, "pitcher")
        f24b = ex.submit(_fetch_statcast_hist, 2024, "batter")
        f24p = ex.submit(_fetch_statcast_hist, 2024, "pitcher")
        fmlb = ex.submit(_fetch_mlb_ops_era, SEASON_YEAR)
        fcur = ex.submit(_fetch_statcast_current, SEASON_YEAR)
        results = {}
        for k, f in [("h25b",f25b),("h25p",f25p),("h24b",f24b),("h24p",f24p),("mlb",fmlb),("cur",fcur)]:
            try: results[k] = f.result(timeout=25)
            except: results[k] = {} if k not in ("mlb","cur") else ({},{})
    return results

def fetch_team_projections(standings_df, roster_map):
    """
    Build team projections using PECOTA + Statcast blend.
    Sample-size weights: PA/400 for batters, IP/150 SP / IP/40 RP.
    Statcast: current 2026 (sample-weighted) + 2025 hist (35%) + 2024 hist (20%).
    PECOTA: 65% of prior signal weight.
    Active roster filter: IL players get 10x downweight vs active players.
    """
    ph, pp = _pecota()
    all_ids = list(TEAM_INFO.keys())
    det = {t:{"batters":[], "sp":[], "rp":[]} for t in all_ids}
    team_pa, team_ip = {}, {}
    if standings_df is not None and not standings_df.empty:
        for _, row in standings_df.iterrows():
            gp = max(int(row.get("games_played",0)),1); tid = int(row["team_id"])
            team_pa[tid] = gp * 38; team_ip[tid] = gp * 9.0

    # Load all Statcast signals in parallel
    sc = _load_statcast_all()
    h25b = sc.get("h25b", {}); h25p = sc.get("h25p", {})
    h24b = sc.get("h24b", {}); h24p = sc.get("h24p", {})
    mlb_ops, mlb_era = sc.get("mlb", ({}, {}))
    cur_bat, cur_pit = sc.get("cur", ({}, {}))

    rows = []
    for tid in all_ids:
        active_ids = roster_map.get(tid, {}).get("active", set())
        il_ids     = roster_map.get(tid, {}).get("il", set())
        ph_team = ph[ph["team_id"] == tid]; pp_team = pp[pp["team_id"] == tid]

        # ── Batting ───────────────────────────────────────────────────────────
        lineup = ph_team.sort_values("pa", ascending=False).head(9)
        if not lineup.empty:
            # Active players get full weight, IL players get 10x downweight
            roster_weights = [
                600.0 if r["mlbid"] in active_ids else
                (10.0 if r["mlbid"] in il_ids else 300.0)
                for _, r in lineup.iterrows()
            ]
            pecota_ops = float(np.average(lineup["ops"].fillna(LEAGUE_AVG_OPS), weights=roster_weights))
        else:
            pecota_ops = LEAGUE_AVG_OPS
        pecota_ops = float(np.clip(pecota_ops, 0.620, 0.850))

        # Sample-size weight for current Statcast (threshold: 400 PA)
        cur_pa = float(team_pa.get(tid, 0))
        w_cur = min(cur_pa / 400.0, 1.0)
        w_prior = 1.0 - w_cur

        # Current xwOBA (sample-weighted)
        cur_xwoba = LEAGUE_AVG_XWOBA
        if isinstance(cur_bat, dict) and tid in cur_bat:
            d = cur_bat[tid]
            w_this = min(d.get("sample", 0) / (400.0 * 9), 1.0)
            cur_xwoba = d["stat"] * w_this + LEAGUE_AVG_XWOBA * (1 - w_this)
        elif isinstance(mlb_ops, dict) and tid in mlb_ops:
            cur_xwoba = float(mlb_ops[tid]) * 0.43

        # Blend: current + 2025 hist + 2024 hist + PECOTA prior
        xwoba = (w_cur * cur_xwoba +
                 w_prior * 0.35 * h25b.get(tid, LEAGUE_AVG_XWOBA) +
                 w_prior * 0.20 * h24b.get(tid, LEAGUE_AVG_XWOBA) +
                 w_prior * 0.45 * LEAGUE_AVG_XWOBA)

        sc_bat_adj = (xwoba / LEAGUE_AVG_XWOBA - 1.0) * 0.30
        team_ops = float(np.clip(pecota_ops * (1 + sc_bat_adj), 0.620, 0.850))
        proj_rpg = float(np.clip((team_ops / LEAGUE_AVG_OPS) * LEAGUE_AVG_RPG, 2.5, 7.5))

        # ── Pitching ─────────────────────────────────────────────────────────
        sp = pp_team[pp_team["role"] == "SP"].sort_values("ip", ascending=False)
        rp = pp_team[pp_team["role"] == "RP"].sort_values("ip", ascending=False)

        def calc_staff_era(df, role):
            if df.empty or df["ip"].sum() == 0: return LEAGUE_AVG_ERA
            # Cap IP: 150 for SP, 40 for RP (per blueprint)
            cap = 150.0 if role == "SP" else 40.0
            capped_ip = df["ip"].clip(upper=cap)
            blended = (df["fip"].fillna(LEAGUE_AVG_FIP)*0.7 + df["era"].fillna(LEAGUE_AVG_ERA)*0.3).clip(2.0, 7.5)
            if capped_ip.sum() == 0: return LEAGUE_AVG_ERA
            return float(np.average(blended, weights=capped_ip))

        sp_era_base = float(np.clip(calc_staff_era(sp, "SP"), 2.80, 5.50))
        rp_era_base = float(np.clip(calc_staff_era(rp, "RP"), 3.00, 5.50))

        # Sample-size weight for pitching Statcast (threshold: 150 IP SP / 40 IP RP)
        cur_ip = float(team_ip.get(tid, 0))
        w_cur_ip = min(cur_ip / 150.0, 1.0)
        w_prior_ip = 1.0 - w_cur_ip

        cur_xera = LEAGUE_AVG_XERA
        if isinstance(cur_pit, dict) and tid in cur_pit:
            d = cur_pit[tid]
            w_this = min(d.get("sample", 0) / 150.0, 1.0)
            cur_xera = d["stat"] * w_this + LEAGUE_AVG_XERA * (1 - w_this)
        elif isinstance(mlb_era, dict) and tid in mlb_era:
            cur_xera = float(mlb_era[tid])

        xera = (w_cur_ip * cur_xera +
                w_prior_ip * 0.35 * h25p.get(tid, LEAGUE_AVG_XERA) +
                w_prior_ip * 0.20 * h24p.get(tid, LEAGUE_AVG_XERA) +
                w_prior_ip * 0.45 * LEAGUE_AVG_XERA)

        sc_pit_adj = (xera / LEAGUE_AVG_XERA - 1.0) * 0.30
        sp_era = float(np.clip(sp_era_base * (1 + sc_pit_adj), 2.80, 5.50))
        rp_era = float(np.clip(rp_era_base * (1 + sc_pit_adj), 3.00, 5.50))
        proj_rapg = float(np.clip(
            (sp_era/LEAGUE_AVG_ERA)*LEAGUE_AVG_RPG*LEAGUE_SP_IP_SHARE +
            (rp_era/LEAGUE_AVG_ERA)*LEAGUE_AVG_RPG*LEAGUE_RP_IP_SHARE, 2.5, 7.5))

        proj_wp = proj_rpg**PYTHAG_EXPONENT / (proj_rpg**PYTHAG_EXPONENT + proj_rapg**PYTHAG_EXPONENT)

        # IL WARP from PECOTA for active roster players not on active list
        il_warp = float(ph[(ph["team_id"]==tid) & (ph["mlbid"].isin(il_ids))]["warp"].clip(lower=0).sum())

        rows.append({
            "team_id": tid, "proj_runs_per_game": round(proj_rpg, 3),
            "proj_ra_per_game": round(proj_rapg, 3), "proj_win_pct": round(proj_wp, 4),
            "il_warp": round(il_warp, 2), "proj_source": "PECOTA+Statcast"
        })
        det[tid]["batters"] = [{"name": r["name"], "pa": int(r["pa"]), "ops": round(float(r["ops"]), 3), "drc+": int(r.get("drc_plus",100))} for _, r in lineup.iterrows()]
    return pd.DataFrame(rows), det

def pythag(rs, ra):
    if rs <= 0 or ra <= 0: return 0.500
    return rs ** PYTHAG_EXPONENT / (rs ** PYTHAG_EXPONENT + ra ** PYTHAG_EXPONENT)

def build_master(std, prj):
    df = std.copy()
    merge_cols = ["team_id", "proj_win_pct", "proj_runs_per_game", "proj_ra_per_game", "proj_source", "il_warp"]
    df = df.merge(prj[merge_cols], on="team_id", how="left")
    df["pythag_win_pct"] = df.apply(lambda r: pythag(r["runs_scored"], r["runs_allowed"]), axis=1)
    gp = df["games_played"].clip(0, 162)
    
    # FIX: Regress Pythag for small sample size (standard Tango regression)
    df["pythag_win_pct"] = df["pythag_win_pct"] * (gp / (gp + 80.0)) + 0.500 * (80.0 / (gp + 80.0))
    
    base_proj_w = (0.70 - (gp / 162.0) * 0.25).clip(0.45, 0.70)
    il_frac = (df["il_warp"] / TYPICAL_TEAM_WARP).clip(0.0, 0.50)
    adj_pyth_w = (1.0 - base_proj_w) * (1.0 - il_frac)
    adj_proj_w = 1.0 - adj_pyth_w
    
    df["blended_win_pct"] = (df["proj_win_pct"]*adj_proj_w + df["pythag_win_pct"]*adj_pyth_w).clip(0.20, 0.80)
    df["games_remaining"] = (162 - gp).clip(0, 162)
    return df

def compute_buyer_seller(df):
    df = df.copy()
    df["pythag_expected_wins"] = df["pythag_win_pct"] * df["games_played"]
    df["luck_wins"] = df["wins"] - df["pythag_expected_wins"]
    df["rd_per_162"] = (df["run_differential"] / df["games_played"].clip(1)) * 162
    rd_mod = (-df["rd_per_162"] * 0.02 * ((df["games_played"] - 50) / 50.0).clip(0, 1)).clip(-2.0, 2.0)
    luck_mod = df["luck_wins"] * 0.5 * ((df["games_played"] - 40) / 60.0).clip(0, 1)
    pre = df["wc_games_back"] + rd_mod + luck_mod
    damp = df["games_played"].apply(lambda g: 0.5 if g <= 30 else 0.75 if g <= 55 else 0.9 if g <= 81 else 1.0)
    dp = min(max((date.today() - date(SEASON_YEAR, 4, 1)).days / max((date(SEASON_YEAR, 6, 15) - date(SEASON_YEAR, 4, 1)).days, 1), 0.4), 1.0)
    df["adjusted_score"] = pre * damp * dp
    df["base_adj"] = np.clip(-df["adjusted_score"] * 0.015, -0.12, 0.07)
    df["tier"] = df["adjusted_score"].apply(lambda s: "hard_seller" if s >= 8 else "soft_seller" if s >= 4 else "neutral" if s >= -3 else "soft_buyer" if s >= -8 else "hard_buyer")
    df["tier_label"] = df["tier"].map(TIER_LABELS)
    return df

def apply_ramp(df, ramp):
    df = df.copy()
    df["ramped_adj"] = df["base_adj"] * ramp
    df["adj_win_pct"] = (df["blended_win_pct"] + df["ramped_adj"]).clip(0.20, 0.80)
    return df

def apply_luck_regression(df, factor=0.40):
    df = df.copy()
    gr = (162 - df["games_played"]).clip(10, 162)
    luck_reg = -(df["luck_wins"] * factor) / gr
    df["adj_win_pct"] = (df["adj_win_pct"] + luck_reg).clip(0.20, 0.80)
    return df

def compute_sos(df, opps):
    if not opps: return df.assign(sos_raw=0.5, sos_label="Average")
    wp = df.set_index("team_id")["adj_win_pct"]
    sos = {t: float(np.mean([wp.get(int(o), 0.5) for o in opps.get(int(t), [])])) if opps.get(int(t)) else 0.5 for t in df["team_id"]}
    df["sos_raw"] = df["team_id"].map(sos)
    p33, p67 = df["sos_raw"].quantile([0.33, 0.67])
    df["sos_label"] = df["sos_raw"].apply(lambda v: "Easy" if v <= p33 else "Hard" if v > p67 else "Average")
    return df

def apply_schedule_adjustment(df, sensitivity=SOS_SENSITIVITY):
    df = df.copy()
    df["sos_adjustment"] = (0.500 - df["sos_raw"]) * sensitivity
    # FIX: Scale SOS impact by sample size (0 early, max at ~half season)
    sos_scale = (df["games_played"] / 81.0).clip(0, 1)
    df["adj_win_pct"] = (df["adj_win_pct"] + df["sos_adjustment"] * sos_scale).clip(0.20, 0.80)
    return df

def log5(a, b): return (a - a*b) / (a + b - 2*a*b + 1e-9)

def _sim_once(mdf, sch, wp_col, rng):
    """Run one set of simulations using the given win% column."""
    tids = mdf["team_id"].tolist(); n = len(tids); idx = {t:i for i,t in enumerate(tids)}
    init = np.array([mdf.set_index("team_id")["wins"].get(t,0) for t in tids], dtype=np.float32)
    wp = mdf.set_index("team_id")[wp_col].to_dict()
    rem = get_remaining_games(sch)
    if rem.empty:
        proj = {t: float(init[i] + wp.get(t,0.5)*(162-int(mdf.set_index("team_id")["games_played"].get(t,0)))) for i,t in enumerate(tids)}
        return proj, {t:0.0 for t in tids}, {t:0.0 for t in tids}, {t:0.0 for t in tids}
    h, a = rem["home_team_id"].values.astype(int), rem["away_team_id"].values.astype(int)
    valid = np.array([(x in idx and y in idx) for x,y in zip(h,a)])
    h, a = h[valid], a[valid]
    ap = np.array([log5(wp.get(x,0.5), wp.get(y,0.5)) for x,y in zip(h,a)], dtype=np.float32)
    hi, ai = np.array([idx[x] for x in h]), np.array([idx[x] for x in a])
    f = np.full((N_SIMULATIONS, n), init, dtype=np.float32)
    if len(h) > 0:
        r = rng.random((N_SIMULATIONS, len(h)), dtype=np.float32)
        hw = (r < ap[np.newaxis,:]).astype(np.float32)
        np.add.at(f,(np.arange(N_SIMULATIONS)[:,None],hi),hw)
        np.add.at(f,(np.arange(N_SIMULATIONS)[:,None],ai),1-hw)
    # Compute odds
    div_map = mdf.set_index("team_id")["division"].to_dict()
    lg_map  = mdf.set_index("team_id")["league"].to_dict()
    div_odds={t:0.0 for t in tids}; po_odds={t:0.0 for t in tids}; ws_odds={t:0.0 for t in tids}
    for sim_i in range(N_SIMULATIONS):
        wins_i = {t:float(f[sim_i][idx[t]]) for t in tids}
        for lg in ["AL","NL"]:
            lg_teams = [t for t in tids if lg_map[t]==lg]
            divs = {}
            for t in lg_teams: divs.setdefault(div_map[t],[]).append(t)
            qualifiers = set()
            for d, dteams in divs.items():
                winner = max(dteams, key=lambda t: wins_i[t]); qualifiers.add(winner); div_odds[winner]+=1
            wc_pool = sorted([t for t in lg_teams if t not in qualifiers], key=lambda t: -wins_i[t])
            for t in wc_pool[:3]: qualifiers.add(t)
            for t in qualifiers: po_odds[t]+=1
            # Simple WS odds
            playoff_list = list(qualifiers)
            r2 = rng.random(len(playoff_list))
            winner = playoff_list[int(r2[0]*len(playoff_list))]
            ws_odds[winner]+=1
    denom = N_SIMULATIONS
    proj_wins_out = {t:float(f.mean(0)[idx[t]]) for t in tids}
    proj_std_out  = {t:float(f.std(0)[idx[t]])  for t in tids}
    return proj_wins_out, {t:v/denom for t,v in div_odds.items()}, {t:v/denom for t,v in po_odds.items()}, {t:v/denom for t,v in ws_odds.items()}

def run_simulation(mdf, sch):
    rng = np.random.default_rng(RANDOM_SEED)
    # Post-deadline simulation (with deadline adjustments)
    pw, dv, po, ws = _sim_once(mdf, sch, "adj_win_pct", rng)
    # Pre-deadline simulation (without deadline adjustments)
    pre_rng = np.random.default_rng(RANDOM_SEED)
    pre_pw, pre_dv, pre_po, pre_ws = _sim_once(mdf, sch, "blended_win_pct", pre_rng)
    return {
        "proj_wins": pw, "proj_wins_std": {t: float(np.std([v for v in pw.values()])*0.5) for t in pw},
        "division_odds": dv, "playoff_odds": po, "ws_odds": ws,
        "pre_deadline_division_odds": pre_dv, "pre_deadline_playoff_odds": pre_po, "pre_deadline_ws_odds": pre_ws,
    }

