def render_projections_tab(mdf, sim):
    st.markdown("## 2026 MLB Season Projections"); st.caption(f"Updated daily · {N_SIMULATIONS:,}-sim Monte Carlo · Sample-Adjusted")
    rows = []
    for _, r in mdf.iterrows():
        t = r["team_id"]; proj_w = int(round(sim['proj_wins'].get(t, r['wins'])))
        rows.append({"Team": r["abbr"], "League": r["league"], "Division": r["division"], "W": int(r["wins"]), "L": int(r["losses"]), "Win%": f"{r['win_pct']:.3f}", "Pythag%": f"{r['pythag_win_pct']:.3f}", "GB (WC)": f"{r['wc_games_back']:.1f}" if r["wc_games_back"] >0 else "—", "Proj W": proj_w, "Proj L": 162 - proj_w, "Status": r.get("tier_label", "Neutral"), "tier": r.get("tier", "neutral"), "SoS": r.get("sos_label", "—")})
    df = pd.DataFrame(rows); c1, c2 = st.columns(2)
    lf = c1.radio("League", ["All", "AL", "NL"], horizontal=True)
    if lf != "All": df = df[df["League"] == lf]
    sel_div = c2.selectbox("Division", ["All Divisions"] + sorted(df["Division"].unique()))
    if sel_div != "All Divisions": df = df[df["Division"] == sel_div]
    st.markdown("---")
    for d in sorted(df["Division"].unique()):
        dd = df[df["Division"]==d].sort_values("Proj W", ascending=False)
        dd["Status"] = dd.apply(lambda r: f"{TIER_EMOJI.get(r['tier'],'⚪')} {r['Status']}", axis=1)
        st.markdown(f"### {d}"); st.dataframe(dd, hide_index=True, width="stretch")

    # Export
    st.markdown("---")
    export_df = df.drop(columns=["tier"], errors="ignore")
    csv = export_df.to_csv(index=False)
    st.download_button("📥 Export Standings & Projections (CSV)", csv, "mlb_2026_projections.csv", "text/csv")

def render_deadline_tab(mdf, sim):
    st.markdown("## Trade Deadline Impact")
    rows = []
    for _, r in mdf.iterrows():
        t = r["team_id"]; pre_po, post_po = sim.get("pre_deadline_playoff_odds",{}).get(t,0), sim.get("playoff_odds",{}).get(t,0)
        rows.append({"Team": r["abbr"], "tier": r.get("tier", "neutral"), "Status": r.get("tier_label", "Neutral"), "PO Delta": post_po-pre_po})
    comp = pd.DataFrame(rows).sort_values("PO Delta")
    colors = [TIER_COLORS.get(t, "#7f7f7f") for t in comp["tier"]]
    fig = go.Figure(go.Bar(x=comp["Team"], y=(comp["PO Delta"]*100).round(1), marker_color=colors, text=(comp["PO Delta"]*100).round(1).apply(lambda v: f"{v:+.1f}%"), textposition="outside"))
    fig.update_layout(title="Playoff Odds Change", plot_bgcolor="rgba(0,0,0,0)", height=400); fig.add_hline(y=0, line_dash="dash")
    st.plotly_chart(fig, use_container_width=True)

def render_team_tab(mdf, sim):
    opts = sorted([(r["name"], r["team_id"]) for _, r in mdf.iterrows()])
    sel  = st.selectbox("Select Team", [o[0] for o in opts], key="team_sel")
    tid  = next(o[1] for o in opts if o[0]==sel)
    r    = mdf[mdf["team_id"]==tid].iloc[0]
    tier = r.get("tier","neutral")

    st.markdown(f"## {r['name']} ({r['abbr']})")
    st.caption(f"{r['division']} · {TIER_EMOJI.get(tier,'⚪')} {r.get('tier_label','Neutral')} · Source: {r.get('proj_source','Unknown')}")

    pw   = sim["proj_wins"].get(tid, r["wins"])
    ps   = sim.get("proj_wins_std",{}).get(tid, 5.0)
    pw_i = int(round(pw)); pl_i = int(round(162-pw))

    st.markdown("### Season Projections")
    m1,m2,m3,m4,m5,m6 = st.columns(6)
    m1.metric("Record",   f"{int(r['wins'])}-{int(r['losses'])}")
    m2.metric("Proj Rec", f"{pw_i}-{pl_i}", f"±{ps:.1f}W")
    m3.metric("Div%",     f"{sim.get('division_odds',{}).get(tid,0):.1%}")
    m4.metric("Playoff%", f"{sim.get('playoff_odds',{}).get(tid,0):.1%}")
    m5.metric("WS%",      f"{sim.get('ws_odds',{}).get(tid,0):.2%}")
    m6.metric("SoS",      r.get("sos_label","—"))

    pre_po  = sim.get("pre_deadline_playoff_odds",{}).get(tid,0)
    post_po = sim.get("playoff_odds",{}).get(tid,0)
    pre_ws  = sim.get("pre_deadline_ws_odds",{}).get(tid,0)
    post_ws = sim.get("ws_odds",{}).get(tid,0)
    pre_dv  = sim.get("pre_deadline_division_odds",{}).get(tid,0)
    post_dv = sim.get("division_odds",{}).get(tid,0)

    st.markdown("### Deadline Impact")
    d1,d2,d3 = st.columns(3)
    d1.metric("Division Odds", f"{post_dv:.1%}", f"{post_dv-pre_dv:+.1%} vs pre-DL")
    d2.metric("Playoff Odds",  f"{post_po:.1%}", f"{post_po-pre_po:+.1%} vs pre-DL")
    d3.metric("WS Odds",       f"{post_ws:.2%}", f"{post_ws-pre_ws:+.2%} vs pre-DL")

    st.markdown("---")
    st.markdown("### Classification Drivers")
    ci1, ci2 = st.columns(2)
    with ci1:
        st.markdown("**Inputs**")
        for k,v in [
            ("WC Games Back",          f"{r.get('wc_games_back',0):.1f}"),
            ("Run Diff/162",           f"{r.get('rd_per_162',0):+.0f}"),
            ("Actual Win%",            f"{r.get('win_pct',0):.3f}"),
            ("Pythagorean Win%",       f"{r.get('pythag_win_pct',0):.3f}"),
            ("Player Proj Win%",       f"{r.get('proj_win_pct',0):.3f}"),
            ("Blended Win%",           f"{r.get('blended_win_pct',0):.3f}"),
            ("Luck (wins +/-)",        f"{r.get('luck_wins',0):+.1f}"),
            ("IL WARP (missing)",      f"{r.get('il_warp',0):.1f}"),
        ]:
            st.markdown(f"- **{k}:** {v}")
    with ci2:
        st.markdown("**Score & Adjustments**")
        for k,v in [
            ("Adjusted Score",        f"{r.get('adjusted_score',0):.2f}"),
            ("Base Win Adj",          f"{r.get('base_adj',0):+.3f}"),
            ("Ramped Adj (today)",    f"{r.get('ramped_adj',0):+.3f}"),
            ("Luck Regression",       f"{-(r.get('luck_wins',0)*0.40)/max(r.get('games_remaining',1),1):+.4f}"),
            ("SoS Adjustment",        f"{r.get('sos_adjustment',0):+.4f}"),
            ("Final Adj Win%",        f"{r.get('adj_win_pct',0):.3f}"),
            ("Deadline Ramp",         f"{get_deadline_ramp_factor():.0%}"),
        ]:
            st.markdown(f"- **{k}:** {v}")

    st.markdown("---")
    st.markdown("### Projected Win Distribution")
    std_ = max(ps, 3.0); x = np.linspace(pw-4*std_, pw+4*std_, 200)
    y    = np.exp(-0.5*((x-pw)/std_)**2)/(std_*np.sqrt(2*np.pi))
    fig  = go.Figure(go.Scatter(x=x, y=y, fill="tozeroy", line=dict(color="#636efa")))
    fig.add_vline(x=pw, line_dash="dash", line_color="#ef553b",
                  annotation_text=f"Proj: {pw:.1f}W", annotation_position="top right")
    fig.update_layout(xaxis_title="Final Wins", height=300,
                      plot_bgcolor="rgba(0,0,0,0)", paper_bgcolor="rgba(0,0,0,0)",
                      yaxis=dict(showticklabels=False), showlegend=False)
    st.plotly_chart(fig, use_container_width=True)

def render_methodology_tab():
    st.markdown("## 📖 Methodology & Model Architecture")
    st.caption(f"Data last updated: {get_last_updated()}")
    st.markdown("""
Built around one core insight: **no existing projection system accounts for what happens when a team sells at the trade deadline.**
The BP analyst who inspired this model said it best: teams underperforming due to injuries are being systematically undervalued — their playoff odds
don't account for the roster they'll have in August, or for the wins they'll lose by trading away Clay Holmes for prospects.
""")
    with st.expander("📊 Data Pipeline & Sources"):
        st.markdown("""
| Source | Frequency | Purpose |
|---|---|---|
| **MLB Stats API** | Daily | Live standings, schedule, active/40-man rosters, IL codes |
| **Baseball Savant** | Daily | xwOBA/xERA for 2024, 2025, current 2026 (sample-weighted) |
| **PECOTA 2026** | Static (preseason) | Talent baseline — 50th percentile, depth-chart players only |

**Active Roster Filter:** IL players receive 10× downweight vs active players in lineup OPS calculation.
Trades and call-ups update daily via MLB API.
""")
    with st.expander("🔮 Projection Engine — PECOTA + Statcast Blend"):
        st.markdown(f"""
**Step 1 — PECOTA baseline:**
Top 9 hitters by projected PA; active players weighted 600, IL players 10, others 300.
SP vs RP split: GS ≥ 10 = starter. Pitcher ERA = 70% FIP + 30% ERA, IP-capped at 150 (SP) / 40 (RP).
No aging curve applied — PECOTA already prices in age and development.

**Step 2 — Statcast adjustment (sample-size weighted, not date-weighted):**

| Signal | Batters | Pitchers |
|---|---|---|
| Full weight threshold | 400 PA | 150 IP |
| Current 2026 xwOBA/xERA | min(sample/threshold, 1.0) | min(sample/threshold, 1.0) |
| 2025 historical | 35% of prior weight | 35% of prior weight |
| 2024 historical | 20% of prior weight | 20% of prior weight |
| PECOTA (prior) | 45% of prior weight | 45% of prior weight |

A called-up rookie with 40 PA gets 10% current Statcast weight. A full-timer with 400 PA gets 100%.

**Step 3 — Pythagorean blend (IL-adjusted):**

Pythagorean Win% = RS^1.83 / (RS^1.83 + RA^1.83), then regressed toward .500:
```
Pythag_W = GP / (GP + 80)   # Tango regression
```
At 38 GP: 32% Pythag / 68% PECOTA. At 81 GP: 50/50. At 162 GP: 67% Pythag.

**IL WARP adjustment:** IL roster cross-referenced with PECOTA mlbid.
Missing WARP reduces Pythagorean weight: `adj_pythag_w = base_pythag_w × (1 - il_frac)` where `il_frac = min(il_warp / 35, 0.50)`.
""")
    with st.expander("📈 Buyer/Seller Classification"):
        dp = min(max((date.today()-date(SEASON_YEAR,4,1)).days / max((date(SEASON_YEAR,6,15)-date(SEASON_YEAR,4,1)).days,1), 0.4), 1.0)
        st.markdown(f"""
**Score = WC Games Back + run diff modifier + luck modifier**
- Run diff modifier: dampened before 50 GP
- Luck modifier: dampened before 40 GP
- Games-played dampener: 50% at ≤30 GP → 75% at 31–55 → 90% at 56–81 → 100% at 82+
- Deadline proximity confidence: 40% on Apr 1 → 100% by Jun 15 (today: {dp:.0%})

**Tiers and adjustments (fully ramped):**
Hard Seller (≥8): −12% | Soft Seller (4–7.9): −6% | Neutral: ±0% | Soft Buyer (−8 to −3): +4% | Hard Buyer (<−8): +7%

Adjustment formula: `adj = clip(-score × 0.015, -0.12, 0.07)`
""")
    with st.expander("🗓️ Trade Deadline Ramp"):
        st.markdown(f"""
Ramp starts **{DEADLINE_RAMP_START}** → 100% by **{TRADE_DEADLINE}**.
Today's ramp factor: **{get_deadline_ramp_factor():.1%}**

`ramped_adj = base_adj × ramp_factor`
`adj_win_pct = blended_win_pct + ramped_adj`

Before ramp start, no penalty or bonus is applied. The Deadline Impact tab shows the counterfactual at full ramp.
The post-deadline example: replacing 200 IP of 3.3 ERA with 200 IP of 4.5 ERA (Holmes/Peralta/Riley → Jonah Tong etc.) costs ~1.5 wins.
""")
    with st.expander("📉 Luck Regression & SoS"):
        st.markdown(f"""
**Explicit Luck Regression:**
`luck_reg = -(luck_wins × 0.40) / games_remaining`
Applied after deadline ramp. Unlucky teams get a win% boost; lucky teams get a drag.

**Strength of Schedule:**
`sos_adj = (0.500 - avg_opponent_win_pct) × {SOS_SENSITIVITY} × min(GP/81, 1.0)`
Scales from 0% impact early season to full impact by game 81.
Easy schedule → win% boost; hard schedule → win% penalty.
""")
    with st.expander("🎲 Monte Carlo Simulation"):
        st.markdown(f"""
**{N_SIMULATIONS:,} simulations** (vectorized numpy, zero-sum).

Game probability: `Log5(A,B) = (A - A×B) / (A + B - 2×A×B)`

Two parallel runs per sim session:
- **Post-deadline** (adj_win_pct with deadline adjustments): main projection
- **Pre-deadline** (blended_win_pct without adjustments): counterfactual for Deadline Impact tab

Playoff qualification: 3 division winners + 3 wild cards per league.
Zero-sum constraint: total wins = total games played (prevents systematic over-projection).
""")

